package vn.svframe.svframelib.player.particle.type;
import vn.svframe.svframelib.player.particle.*;import vn.svframe.svframelib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import java.util.Map;
public class DoubleRingsParticleEffect extends ParticleEffect{private final double speed,height,radius,rSpeed,yOffset;private double a;public DoubleRingsParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed");height=resolveModifier(m,"height");radius=resolveModifier(m,"radius");rSpeed=resolveModifier(m,"rotation-speed");yOffset=resolveModifier(m,"y-offset");}public DoubleRingsParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed");height=o.getDouble("height");radius=o.getDouble("radius");rSpeed=o.getDouble("rotation-speed");yOffset=o.getDouble("y-offset");}public ParticleEffectType getType(){return ParticleEffectType.DOUBLE_RINGS;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();Vec3d b=pl.getPos();for(int k=0;k<2;k++){double x=a+k*Math.PI;particle.display(pl.getServerWorld(),b.add(radius*Math.cos(x),height+Math.sin(a)*yOffset,radius*Math.sin(x)),speed);}a+=Math.PI/16*rSpeed;if(a>Math.PI*2)a-=Math.PI*2;}}
